changeSet.sql:
ALTER TABLE media RENAME TO media_asset;
ALTER TABLE media_asset RENAME COLUMN path TO storage_key;
ALTER TABLE media_asset RENAME COLUMN content_type TO mime_type;
ALTER TABLE sheet_music_media RENAME COLUMN media_id TO media_asset_id;

ALTER TABLE media_asset
  ADD COLUMN original_filename VARCHAR(500),
  ADD COLUMN file_extension VARCHAR(32),
  ADD COLUMN file_size BIGINT,
  ADD COLUMN sha256 CHAR(64),
  ADD COLUMN status VARCHAR(32);

CREATE OR REPLACE FUNCTION taurus_relative_storage_key(raw_path TEXT)
RETURNS TEXT AS $$
DECLARE
  normalized TEXT := regexp_replace(replace(COALESCE(raw_path, ''), E'\\', '/'), '/+', '/', 'g');
  tenant_code TEXT;
  safe_tenant TEXT;
  marker TEXT;
  marker_position INTEGER;
BEGIN
  SELECT registry.tenant_code
    INTO tenant_code
    FROM public.tenant_schema_registry registry
   WHERE registry.schema_name = current_schema()
   LIMIT 1;

  safe_tenant := lower(regexp_replace(btrim(COALESCE(tenant_code, '')), '[^a-z0-9._-]', '_', 'g'));
  marker := '/' || safe_tenant || '/';
  marker_position := strpos(lower(normalized), marker);

  IF safe_tenant <> '' AND marker_position > 0 THEN
    RETURN substring(normalized FROM marker_position + char_length(marker));
  END IF;
  IF normalized !~ '^([A-Za-z]:/|/)' THEN
    RETURN ltrim(normalized, '/');
  END IF;
  RETURN 'legacy-unresolved/' || md5(normalized) || '/' || regexp_replace(normalized, '^.*/', '');
END;
$$ LANGUAGE plpgsql STABLE;

UPDATE media_asset
   SET storage_key = taurus_relative_storage_key(storage_key),
       original_filename = COALESCE(NULLIF(name, ''), regexp_replace(storage_key, '^.*[\\/]', '')),
       mime_type = COALESCE(NULLIF(mime_type, ''), 'application/octet-stream'),
       file_extension = CASE
         WHEN COALESCE(NULLIF(name, ''), storage_key) ~* '\.[a-z0-9]{1,31}$'
           THEN lower(regexp_replace(COALESCE(NULLIF(name, ''), storage_key), '^.*\.([a-z0-9]{1,31})$', '\1', 'i'))
         ELSE 'bin'
       END,
       file_size = 0,
       sha256 = repeat('0', 64),
       status = 'MIGRATION_PENDING';

ALTER TABLE media_asset
  ALTER COLUMN original_filename SET NOT NULL,
  ALTER COLUMN mime_type SET NOT NULL,
  ALTER COLUMN file_extension SET NOT NULL,
  ALTER COLUMN file_size SET NOT NULL,
  ALTER COLUMN sha256 SET NOT NULL,
  ALTER COLUMN status SET NOT NULL;
ALTER TABLE media_asset
  ADD CONSTRAINT ck_media_asset_storage_key CHECK (
    btrim(storage_key) <> ''
    AND left(storage_key, 1) <> '/'
    AND position(chr(92) IN storage_key) = 0
    AND storage_key !~ '(^|/)\.\.(/|$)'
    AND storage_key !~ '^[A-Za-z]:'
  ),
  ADD CONSTRAINT ck_media_asset_file_size CHECK (file_size >= 0),
  ADD CONSTRAINT ck_media_asset_sha256 CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT ck_media_asset_status CHECK (status IN ('UPLOADING', 'PROCESSING', 'READY', 'INVALID', 'FAILED', 'DELETED', 'MIGRATION_PENDING'));
CREATE UNIQUE INDEX uq_media_asset_storage_key ON media_asset(storage_key);

ALTER TABLE inventory_item_photo ADD COLUMN media_asset_id BIGINT;
INSERT INTO media_asset (
  deleted, insert_by, insert_date, edit_by, edit_date, entity_version, name, description,
  storage_key, original_filename, mime_type, file_extension, file_size, sha256, status
)
SELECT DISTINCT ON (taurus_relative_storage_key(photo.storage_path))
  FALSE, photo.insert_by, photo.insert_date, photo.edit_by, photo.edit_date, 0,
  photo.file_name, NULL, taurus_relative_storage_key(photo.storage_path), photo.file_name,
  photo.content_type,
  CASE WHEN photo.file_name ~* '\.[a-z0-9]{1,31}$'
    THEN lower(regexp_replace(photo.file_name, '^.*\.([a-z0-9]{1,31})$', '\1', 'i'))
    WHEN photo.content_type = 'image/png' THEN 'png' ELSE 'jpg' END,
  photo.file_size,
  CASE WHEN lower(photo.content_digest) ~ '^[0-9a-f]{64}$' THEN lower(photo.content_digest) ELSE repeat('0', 64) END,
  CASE WHEN lower(photo.content_digest) ~ '^[0-9a-f]{64}$' THEN 'READY' ELSE 'MIGRATION_PENDING' END
FROM inventory_item_photo photo
ON CONFLICT (storage_key) DO NOTHING;
UPDATE inventory_item_photo photo
   SET media_asset_id = asset.id
  FROM media_asset asset
 WHERE asset.storage_key = taurus_relative_storage_key(photo.storage_path);
ALTER TABLE inventory_item_photo ALTER COLUMN media_asset_id SET NOT NULL;
ALTER TABLE inventory_item_photo
  ADD CONSTRAINT fk_inventory_item_photo_media_asset
  FOREIGN KEY (media_asset_id) REFERENCES media_asset(id) ON DELETE RESTRICT;
CREATE INDEX idx_inventory_item_photo_media_asset ON inventory_item_photo(media_asset_id);
ALTER TABLE inventory_item_photo
  DROP COLUMN file_name,
  DROP COLUMN content_type,
  DROP COLUMN storage_path,
  DROP COLUMN content_digest,
  DROP COLUMN file_size;

