ALTER TABLE inventory_return_photo ALTER COLUMN media_asset_id SET NOT NULL;
ALTER TABLE inventory_return_photo
  ADD CONSTRAINT fk_inventory_return_photo_media_asset
  FOREIGN KEY (media_asset_id) REFERENCES media_asset(id) ON DELETE RESTRICT;
CREATE INDEX idx_inventory_return_photo_media_asset ON inventory_return_photo(media_asset_id);
ALTER TABLE inventory_return_photo
  DROP COLUMN file_name,
  DROP COLUMN content_type,
  DROP COLUMN storage_path,
  DROP COLUMN content_digest,
  DROP COLUMN file_size;

ALTER TABLE upload_job ADD COLUMN source_media_asset_id BIGINT;
INSERT INTO media_asset (
  deleted, insert_by, insert_date, edit_by, edit_date, entity_version, name, description,
  storage_key, original_filename, mime_type, file_extension, file_size, sha256, status
)
SELECT DISTINCT ON (taurus_relative_storage_key(job.path))
  FALSE, COALESCE(job.insert_by, 'system'), job.insert_date, COALESCE(job.edit_by, 'system'), job.edit_date, 0,
  COALESCE(NULLIF(job.name, ''), 'upload.pdf'), NULL, taurus_relative_storage_key(job.path),
  COALESCE(NULLIF(job.name, ''), 'upload.pdf'), 'application/pdf', 'pdf', 0, repeat('0', 64), 'MIGRATION_PENDING'
FROM upload_job job
ON CONFLICT (storage_key) DO NOTHING;
UPDATE upload_job job
   SET source_media_asset_id = asset.id
  FROM media_asset asset
 WHERE asset.storage_key = taurus_relative_storage_key(job.path);
ALTER TABLE upload_job ALTER COLUMN source_media_asset_id SET NOT NULL;
ALTER TABLE upload_job
  ADD CONSTRAINT fk_upload_job_source_media_asset
  FOREIGN KEY (source_media_asset_id) REFERENCES media_asset(id) ON DELETE RESTRICT;
CREATE INDEX idx_upload_job_source_media_asset ON upload_job(source_media_asset_id);
ALTER TABLE upload_job DROP COLUMN path;

ALTER TABLE inventory_report_export ADD COLUMN media_asset_id BIGINT;
ALTER TABLE inventory_report_export
  ADD CONSTRAINT fk_inventory_report_export_media_asset
  FOREIGN KEY (media_asset_id) REFERENCES media_asset(id) ON DELETE RESTRICT;
CREATE INDEX idx_inventory_report_export_media_asset ON inventory_report_export(media_asset_id);
ALTER TABLE inventory_report_export
  DROP COLUMN file_size,
  DROP COLUMN content_digest;

DROP TRIGGER IF EXISTS trg_media_prepare_soft_delete_cascade ON media_asset;
DROP TRIGGER IF EXISTS trg_media_cascade_soft_delete ON media_asset;

CREATE OR REPLACE FUNCTION taurus_cascade_media_asset_soft_delete()
RETURNS TRIGGER AS $$
DECLARE
  actor TEXT := COALESCE(NULLIF(BTRIM(NEW.edit_by), ''), 'system');
BEGIN
  IF OLD.deleted = FALSE AND NEW.deleted = TRUE THEN
    EXECUTE format(
      'UPDATE %I.sheet_music_media '
      || 'SET deleted = TRUE, edit_by = $1, edit_date = CURRENT_TIMESTAMP '
      || 'WHERE media_asset_id = $2 AND deleted = FALSE',
      TG_TABLE_SCHEMA
    ) USING actor, NEW.id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_media_asset_cascade_soft_delete
  AFTER UPDATE OF deleted ON media_asset
  FOR EACH ROW EXECUTE FUNCTION taurus_cascade_media_asset_soft_delete();

DROP FUNCTION taurus_relative_storage_key(TEXT);
